import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.DoUXNnsN.js";const g=JSON.parse('{"title":"命令行与Linux","description":"","frontmatter":{"title":"命令行与Linux","aliases":["命令行","终端","Shell","Bash","Linux命令","CLI","管道","SSH","chmod"],"tags":["工具与工程","命令行","Linux"],"status":"ai-draft","sources":["https://www.gnu.org/software/bash/manual/bash.html","https://www.gnu.org/software/coreutils/manual/coreutils.html","https://man.openbsd.org/ssh","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":7},"headers":[],"relativePath":"50-工具与工程/命令行与Linux.md","filePath":"50-工具与工程/命令行与Linux.md"}'),s={name:"50-工具与工程/命令行与Linux.md"};function n(c,e,l,p,r,i){return d(),o("div",null,[...e[0]||(e[0]=[a(`<blockquote><p>本篇的命令在本机 <strong>Git Bash</strong>（GNU bash 5.3，Windows 上的 Bash 环境）里实际运行过，&quot;输出&quot;是真实输出。<strong>只有 Linux 才有的行为</strong>（真正生效的 <code>chmod</code>、<code>sudo</code>、<code>apt</code>、<code>systemctl</code>、<code>ps</code> 等）本机无法验证，已标 <strong>⚠ 未验证</strong>。SSH 的密钥生成在本机验证过，<strong>登录远程服务器</strong>没有验证（没有可连的服务器）。</p></blockquote><blockquote><p>读完你应该能：在终端里自如地切换目录、查看和搜索文件；用管道把小命令组合起来分析日志；看懂 <code>-rwxr-xr-x</code> 的含义；生成 SSH 密钥并知道怎么连服务器。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>命令行</strong>是用敲文字命令代替点鼠标来操作电脑的方式；<strong>Shell</strong>（如 Bash）是接收并执行这些命令的程序；<strong>Linux</strong> 是服务器上最常见的操作系统，它的命令体系就是本篇讲的这一套。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>：知道文件、进程、用户是什么。</li><li><a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a>：知道&quot;目录是树形结构&quot;&quot;路径&quot;是什么。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><ol><li><strong>服务器上没有图形界面。</strong> 工厂机房或云上的 Linux 服务器、<a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a> 容器内部，只能用命令行。</li><li><strong>批量与自动化。</strong> 点鼠标改 1000 个文件名要点 1000 次；一条命令搞定，还能写成脚本反复用。</li><li><strong>排查问题。</strong> 日志文件几十万行，没法用记事本打开。<code>grep</code> 一下就能找出所有错误。</li><li><strong>开发工具本来就是命令行的。</strong> <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<code>dotnet</code>、<code>python</code>、<code>npm</code>、<code>docker</code> 都是命令。</li></ol><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="shell、终端、命令的关系" tabindex="-1">Shell、终端、命令的关系 <a class="header-anchor" href="#shell、终端、命令的关系" aria-label="Permalink to &quot;Shell、终端、命令的关系&quot;">​</a></h3><ul><li><strong>终端</strong>：显示文字、接收键盘输入的窗口。</li><li><strong>Shell</strong>：终端里真正解析你命令的程序。Linux 上默认多是 Bash；Windows 自带的是 <a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a> 和 cmd；装了 Git 后多一个 <strong>Git Bash</strong>（本篇实验的环境）。</li><li>一条命令的通用格式：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命令  选项  参数</span></span>
<span class="line"><span>ls    -l    logs</span></span></code></pre></div><p>选项一般以 <code>-</code> 开头（<code>-l</code>），长选项用 <code>--</code>（<code>--help</code>）。短选项可以合并：<code>ls -la</code> 等价于 <code>ls -l -a</code>。想知道某命令怎么用：<code>命令 --help</code>（Linux 上还可以 <code>man 命令</code>；Git Bash 里没有 <code>man</code>）。</p><h3 id="路径" tabindex="-1">路径 <a class="header-anchor" href="#路径" aria-label="Permalink to &quot;路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>写法</th><th>含义</th></tr></thead><tbody><tr><td><code>/</code></td><td>根目录（Linux 所有文件的起点，没有 C 盘 D 盘之分）</td></tr><tr><td><code>~</code></td><td>当前用户的家目录</td></tr><tr><td><code>.</code> / <code>..</code></td><td>当前目录 / 上一级目录</td></tr><tr><td>绝对路径</td><td>从 <code>/</code> 开始，如 <code>/var/log/app.log</code></td></tr><tr><td>相对路径</td><td>从当前目录开始，如 <code>logs/app.log</code></td></tr></tbody></table><p>Linux 路径区分<strong>大小写</strong>（<code>App.log</code> 和 <code>app.log</code> 是两个文件），分隔符是 <code>/</code> 而不是 Windows 的 <code>\\</code>。Git Bash 把 Windows 的 <code>C:\\Users\\Admin</code> 显示成 <code>/c/Users/Admin</code>（本机实测 <code>echo $HOME</code> 输出 <code>/c/Users/Admin</code>）。</p><h3 id="最常用的命令" tabindex="-1">最常用的命令 <a class="header-anchor" href="#最常用的命令" aria-label="Permalink to &quot;最常用的命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>例子</th></tr></thead><tbody><tr><td><code>pwd</code></td><td>显示当前目录</td><td><code>pwd</code></td></tr><tr><td><code>ls</code></td><td>列出文件，<code>-l</code> 详细，<code>-a</code> 含隐藏文件（以 <code>.</code> 开头）</td><td><code>ls -l logs</code></td></tr><tr><td><code>cd</code></td><td>切换目录</td><td><code>cd logs</code>、<code>cd ..</code>、<code>cd ~</code></td></tr><tr><td><code>mkdir</code></td><td>新建目录，<code>-p</code> 连父目录一起建</td><td><code>mkdir -p lab/logs</code></td></tr><tr><td><code>cat</code></td><td>显示文件全部内容</td><td><code>cat app.log</code></td></tr><tr><td><code>head</code> / <code>tail</code></td><td>看开头 / 结尾几行；<code>tail -f</code> 持续跟随新增内容</td><td><code>tail -n 2 app.log</code></td></tr><tr><td><code>wc -l</code></td><td>数行数</td><td><code>wc -l app.log</code></td></tr><tr><td><code>cp</code> / <code>mv</code> / <code>rm</code></td><td>复制 / 移动或改名 / 删除（<strong><code>rm</code> 没有回收站</strong>）</td><td><code>cp a b</code></td></tr><tr><td><code>touch</code></td><td>新建空文件，或更新时间戳</td><td><code>touch x.txt</code></td></tr><tr><td><code>grep</code></td><td>在文本里搜索匹配的行</td><td><code>grep ERROR app.log</code></td></tr><tr><td><code>find</code></td><td>按条件找文件</td><td><code>find . -name &quot;*.log&quot;</code></td></tr><tr><td><code>echo</code></td><td>输出文字</td><td><code>echo hello</code></td></tr></tbody></table><h3 id="管道与重定向" tabindex="-1">管道与重定向 <a class="header-anchor" href="#管道与重定向" aria-label="Permalink to &quot;管道与重定向&quot;">​</a></h3><p>这是命令行最强大的设计：<strong>每个命令只做一件小事，用管道把它们连起来</strong>。像工厂流水线，前一道工序的产出直接传给下一道。</p><ul><li><code>A | B</code>：把 A 的输出作为 B 的输入。</li><li><code>&gt; 文件</code>：把输出<strong>覆盖写</strong>进文件；<code>&gt;&gt; 文件</code>：<strong>追加</strong>到文件末尾。</li><li><code>命令 &amp;&amp; 命令2</code>：前一条成功才执行后一条；<code>||</code>：前一条失败才执行。</li><li>每个命令结束时有一个<strong>退出码</strong>，<code>0</code> 表示成功，非 0 表示失败；<code>$?</code> 取上一条命令的退出码。</li></ul><h3 id="权限-看懂-rwxr-xr-x" tabindex="-1">权限：看懂 -rwxr-xr-x <a class="header-anchor" href="#权限-看懂-rwxr-xr-x" aria-label="Permalink to &quot;权限：看懂 -rwxr-xr-x&quot;">​</a></h3><p>在 Linux 里 <code>ls -l</code> 的第一列像这样：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-rwxr-xr--</span></span>
<span class="line"><span>│└┬┘└┬┘└┬┘</span></span>
<span class="line"><span>│ │  │  └─ 其他人 (other)：r-- 只读</span></span>
<span class="line"><span>│ │  └──── 所属组 (group)：r-x 读、执行</span></span>
<span class="line"><span>│ └─────── 所有者 (owner)：rwx 读、写、执行</span></span>
<span class="line"><span>└───────── 类型：- 普通文件，d 目录</span></span></code></pre></div><p><code>r</code>=读(4)、<code>w</code>=写(2)、<code>x</code>=执行(1)。数字相加：<code>rwx</code>=7，<code>r-x</code>=5，<code>r--</code>=4。所以 <code>chmod 755 run.sh</code> 表示所有者 rwx、其余人 r-x；<code>chmod 600 key</code> 表示只有所有者能读写（SSH 私钥要求这样）。对目录来说，<code>x</code> 的意思是&quot;允许进入&quot;。</p><blockquote><p><strong>⚠ 在本机（Git Bash on Windows）上 chmod 不生效</strong>：我实测 <code>chmod 755 run.sh2</code> 之后 <code>ls -l</code> 仍显示 <code>-rw-r--r--</code>，再 <code>chmod 600</code> 也没变——Windows 的 NTFS 不用这套权限模型，Git Bash 只是在模拟。所以权限这一节的实际效果请在真正的 Linux（或 WSL、Docker 容器）里验证，<strong>⚠ 未在本机验证</strong>。</p></blockquote><h3 id="ssh-安全地登录远程机器" tabindex="-1">SSH：安全地登录远程机器 <a class="header-anchor" href="#ssh-安全地登录远程机器" aria-label="Permalink to &quot;SSH：安全地登录远程机器&quot;">​</a></h3><p>SSH（Secure Shell）让你通过网络，在自己电脑的终端里操作远程服务器，通信是加密的。基本用法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh 用户名@服务器地址</span></span>
<span class="line"><span>ssh -p 2222 admin@192.168.1.10        # 端口不是默认的 22 时用 -p 指定</span></span></code></pre></div><p><strong>密钥登录</strong>比密码更安全，也方便自动化。原理：你生成一对钥匙——<strong>私钥</strong>（留在自己电脑，绝不能给别人）和<strong>公钥</strong>（放到服务器的 <code>~/.ssh/authorized_keys</code>）。登录时服务器用公钥出一道题，只有持有私钥的人能答对。</p><h2 id="逐步例子-用管道分析一份日志" tabindex="-1">逐步例子：用管道分析一份日志 <a class="header-anchor" href="#逐步例子-用管道分析一份日志" aria-label="Permalink to &quot;逐步例子：用管道分析一份日志&quot;">​</a></h2><p>下面全部在本机 Git Bash 实际运行过。先造一份有 6 行的日志 <code>logs/app.log</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts=10:01 level=INFO msg=start</span></span>
<span class="line"><span>ts=10:02 level=ERROR msg=db timeout</span></span>
<span class="line"><span>ts=10:03 level=INFO msg=ok</span></span>
<span class="line"><span>ts=10:04 level=ERROR msg=db timeout</span></span>
<span class="line"><span>ts=10:05 level=WARN msg=slow</span></span>
<span class="line"><span>ts=10:06 level=ERROR msg=disk full</span></span></code></pre></div><p><strong>问题 1：有几行？前 2 行、后 2 行是什么？</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wc -l logs/app.log</span></span>
<span class="line"><span>6 logs/app.log</span></span>
<span class="line"><span>$ head -n 2 logs/app.log</span></span>
<span class="line"><span>ts=10:01 level=INFO msg=start</span></span>
<span class="line"><span>ts=10:02 level=ERROR msg=db timeout</span></span>
<span class="line"><span>$ tail -n 2 logs/app.log</span></span>
<span class="line"><span>ts=10:05 level=WARN msg=slow</span></span>
<span class="line"><span>ts=10:06 level=ERROR msg=disk full</span></span></code></pre></div><p><strong>问题 2：有多少条错误？</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ grep ERROR logs/app.log</span></span>
<span class="line"><span>ts=10:02 level=ERROR msg=db timeout</span></span>
<span class="line"><span>ts=10:04 level=ERROR msg=db timeout</span></span>
<span class="line"><span>ts=10:06 level=ERROR msg=disk full</span></span>
<span class="line"><span>$ grep -c ERROR logs/app.log</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>$ grep ERROR logs/app.log | wc -l</span></span>
<span class="line"><span>3</span></span></code></pre></div><p><code>grep -c</code> 和 <code>grep | wc -l</code> 结果一样，后一种展示了管道：grep 的输出直接喂给 wc。</p><p><strong>问题 3：哪种错误最多？</strong> 这是经典的&quot;统计频次&quot;流水线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ grep ERROR logs/app.log | sed &#39;s/.*msg=//&#39; | sort | uniq -c | sort -rn</span></span>
<span class="line"><span>      2 db timeout</span></span>
<span class="line"><span>      1 disk full</span></span></code></pre></div><p>逐道工序看：</p><table tabindex="0"><thead><tr><th>步骤</th><th>命令</th><th>输出变成</th></tr></thead><tbody><tr><td>1</td><td><code>grep ERROR logs/app.log</code></td><td>3 行错误日志</td></tr><tr><td>2</td><td><code>sed &#39;s/.*msg=//&#39;</code></td><td>把每行里 <code>msg=</code> 及之前的内容删掉，只剩原因：<code>db timeout</code>、<code>db timeout</code>、<code>disk full</code></td></tr><tr><td>3</td><td><code>sort</code></td><td>排序，让相同的行挨在一起</td></tr><tr><td>4</td><td><code>uniq -c</code></td><td>合并相邻重复行并在前面加计数</td></tr><tr><td>5</td><td><code>sort -rn</code></td><td>按数字从大到小排序</td></tr></tbody></table><p><strong>问题 4：各级别日志各多少条？</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cut -d&#39; &#39; -f2 logs/app.log | sort | uniq -c</span></span>
<span class="line"><span>      3 level=ERROR</span></span>
<span class="line"><span>      2 level=INFO</span></span>
<span class="line"><span>      1 level=WARN</span></span></code></pre></div><p><code>cut -d&#39; &#39; -f2</code> 以空格分隔，取第 2 列。</p><p><strong>重定向与退出码</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ grep ERROR logs/app.log &gt; errors.txt     # 覆盖写</span></span>
<span class="line"><span>$ echo &quot;extra&quot; &gt;&gt; errors.txt               # 追加</span></span>
<span class="line"><span>$ cat errors.txt</span></span>
<span class="line"><span>ts=10:02 level=ERROR msg=db timeout</span></span>
<span class="line"><span>ts=10:04 level=ERROR msg=db timeout</span></span>
<span class="line"><span>ts=10:06 level=ERROR msg=disk full</span></span>
<span class="line"><span>extra</span></span>
<span class="line"><span>$ ls nonexist</span></span>
<span class="line"><span>ls: cannot access &#39;nonexist&#39;: No such file or directory</span></span>
<span class="line"><span>$ echo &quot;exit=$?&quot;</span></span>
<span class="line"><span>exit=2</span></span>
<span class="line"><span>$ mkdir x &amp;&amp; echo made || echo failed      # 第一次</span></span>
<span class="line"><span>made</span></span>
<span class="line"><span>$ mkdir x &amp;&amp; echo made || echo failed      # 第二次，x 已存在</span></span>
<span class="line"><span>mkdir: cannot create directory ‘x’: File exists</span></span>
<span class="line"><span>failed</span></span></code></pre></div><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ol><li>打开 Git Bash（装了 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 后右键菜单里有）。<code>mkdir -p lab/logs &amp;&amp; cd lab</code>，用上面的内容造出 <code>logs/app.log</code>（可用 <code>printf</code> 或编辑器）。</li><li>照&quot;逐步例子&quot;的 4 个问题各跑一遍，输出应与上面一致。</li><li><strong>自己加一题</strong>：改日志，再加两行 <code>level=ERROR msg=disk full</code>，重跑问题 3，<code>disk full</code> 应变成 3 次排第一。</li><li><strong>生成 SSH 密钥</strong>（本机已验证）：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ssh-keygen -t ed25519 -f demo_key -N &quot;&quot; -C &quot;demo@lab&quot;</span></span>
<span class="line"><span>Generating public/private ed25519 key pair.</span></span>
<span class="line"><span>Your identification has been saved in demo_key</span></span>
<span class="line"><span>Your public key has been saved in demo_key.pub</span></span></code></pre></div><p>目录下出现 <code>demo_key</code>（私钥，第一行是 <code>-----BEGIN OPENSSH PRIVATE KEY-----</code>）和 <code>demo_key.pub</code>（公钥，一行文本，以 <code>ssh-ed25519 AAAA...</code> 开头）。<code>-N &quot;&quot;</code> 表示不设密码短语，<strong>仅限练习</strong>，真实使用建议设置。做完删除这两个文件。</p><ol start="5"><li><strong>（需要 Linux 环境，⚠ 未在本机验证）</strong> 把公钥发到服务器：<code>ssh-copy-id 用户@服务器</code>，之后 <code>ssh 用户@服务器</code> 免密登录。</li><li><strong>（⚠ 未验证）</strong> 在 Linux 或 WSL 里验证权限：<code>touch a.sh; ls -l a.sh</code> → <code>chmod 755 a.sh; ls -l a.sh</code>（应变成 <code>-rwxr-xr-x</code>）→ <code>chmod 600 a.sh</code>（应变成 <code>-rw-------</code>）。</li></ol><h2 id="linux-才有的常用命令-⚠-未在本机验证" tabindex="-1">Linux 才有的常用命令（⚠ 未在本机验证） <a class="header-anchor" href="#linux-才有的常用命令-⚠-未在本机验证" aria-label="Permalink to &quot;Linux 才有的常用命令（⚠ 未在本机验证）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>sudo 命令</code></td><td>以管理员（root）身份执行</td></tr><tr><td><code>apt install xxx</code>（Debian/Ubuntu）、<code>yum</code>/<code>dnf</code>（RedHat 系）</td><td>安装软件</td></tr><tr><td><code>ps aux</code>、<code>top</code></td><td>查看进程 / 实时资源占用</td></tr><tr><td><code>kill 进程号</code></td><td>结束进程</td></tr><tr><td><code>df -h</code>、<code>du -sh 目录</code></td><td>看磁盘空间 / 目录大小</td></tr><tr><td><code>systemctl status xxx</code></td><td>查看服务状态（systemd）</td></tr><tr><td><code>journalctl -u xxx</code></td><td>查看服务日志</td></tr><tr><td><code>chmod</code>、<code>chown</code></td><td>改权限 / 改所有者</td></tr><tr><td><code>scp</code></td><td>通过 SSH 复制文件</td></tr></tbody></table><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因与办法</th></tr></thead><tbody><tr><td><code>command not found</code></td><td>命令拼错，或程序所在目录不在 <code>PATH</code> 里，见 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a></td></tr><tr><td><code>Permission denied</code></td><td>没有权限；检查 <code>ls -l</code>，或需要 <code>sudo</code>；脚本执行不了要有 <code>x</code> 权限</td></tr><tr><td>文件名带空格，命令把它当成两个参数</td><td>用引号包起来：<code>cat &quot;my file.txt&quot;</code></td></tr><tr><td><code>rm -rf</code> 删错了</td><td>没有回收站。养成先 <code>ls</code> 同样的路径确认再 <code>rm</code> 的习惯；特别警惕 <code>rm -rf /</code> 和变量为空的 <code>rm -rf $DIR/*</code></td></tr><tr><td><code>&gt;</code> 把文件内容冲掉了</td><td><code>&gt;</code> 是覆盖，追加用 <code>&gt;&gt;</code></td></tr><tr><td>Windows 写的脚本在 Linux 报 <code>bad interpreter</code> / <code>^M</code></td><td>换行符是 CRLF，需转成 LF</td></tr><tr><td>SSH 报 <code>Permission denied (publickey)</code></td><td>公钥没放进服务器的 <code>authorized_keys</code>，或私钥权限太宽（应为 600）</td></tr><tr><td>SSH 私钥提示 <code>UNPROTECTED PRIVATE KEY FILE</code></td><td>私钥权限必须只有自己可读：<code>chmod 600 私钥</code></td></tr><tr><td><code>curl http://localhost:端口</code> 返回 503</td><td>本机设了代理变量，curl 把本地请求也发给代理；用 <code>curl --noproxy &#39;*&#39; ...</code>，见 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a></td></tr><tr><td>中文乱码</td><td>终端与文件的字符编码不一致，统一用 UTF-8</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 用一条命令统计 <code>app.log</code> 里 <code>WARN</code> 的行数。</p><p>答：<code>grep -c WARN app.log</code>，本例输出 <code>1</code>。</p><p><strong>2.</strong> 解释 <code>ls -l | grep &quot;^d&quot;</code> 做了什么。</p><p>答：<code>ls -l</code> 的第一个字符为 <code>d</code> 表示目录，<code>grep &quot;^d&quot;</code> 筛出以 <code>d</code> 开头的行，所以是&quot;只列出当前目录下的子目录&quot;。（<code>^</code> 表示行首，是 <a href="/Encyclopedia/20-编程语言/Python/正则表达式">正则表达式</a> 的写法。）</p><p><strong>3.</strong> <code>chmod 640 secret.txt</code> 之后，各类用户有什么权限？</p><p>答：6=rw-（所有者读写），4=r--（同组只读），0=---（其他人无权限）。</p><p><strong>4.</strong> <code>cmd1 &amp;&amp; cmd2 || cmd3</code> 什么时候执行 cmd3？</p><p>答：cmd1 失败时（跳过 cmd2 后执行 cmd3），或者 cmd1 成功但 cmd2 失败时。</p><p><strong>5.</strong> 为什么 SSH 私钥绝不能发给别人？</p><p>答：持有私钥就能冒充你登录所有放了对应公钥的服务器。公钥可以公开，私钥不行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Shell 解析命令；命令 = 命令名 + 选项 + 参数；<code>--help</code> 查用法。</li><li>管道 <code>|</code> 把小命令串成流水线，<code>&gt;</code>/<code>&gt;&gt;</code> 写文件，<code>&amp;&amp;</code>/<code>||</code> 依据退出码控制流程。</li><li>权限三组 rwx（所有者、组、其他），数字 r4 w2 x1；Windows 上的 Git Bash 里 chmod 不真正生效。</li><li>SSH 用密钥对登录：私钥自留，公钥放服务器。</li><li>Windows 用户还要学 <a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>：它的管道传的是<strong>对象</strong>而不是文本。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>、<a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>、<a href="/Encyclopedia/20-编程语言/Python/正则表达式">正则表达式</a>、<a href="/Encyclopedia/50-工具与工程/日志">日志</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Bash 参考手册：<a href="https://www.gnu.org/software/bash/manual/bash.html" target="_blank" rel="noreferrer">https://www.gnu.org/software/bash/manual/bash.html</a></li><li>GNU Coreutils 手册（ls、cp、sort、uniq 等）：<a href="https://www.gnu.org/software/coreutils/manual/coreutils.html" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/manual/coreutils.html</a></li><li>OpenSSH <code>ssh</code> 手册页：<a href="https://man.openbsd.org/ssh" target="_blank" rel="noreferrer">https://man.openbsd.org/ssh</a></li></ul>`,73)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
